def closestInGrid(grid, target):
    m, n = len(grid), len(grid[0])
    row, col = 0, n - 1
    best = grid[0][n - 1]
    while row < m and col >= 0:
        v = grid[row][col]
        if abs(v - target) < abs(best - target) or (abs(v - target) == abs(best - target) and v < best):
            best = v
        if v == target:
            return v
        if v > target:
            col -= 1
        else:
            row += 1
    return best
